params.fn:
function(ctx){
  var descSelectors=['h1'];
  var desc='';
  for(var i=0;i<descSelectors.length;i++){
    var el=document.querySelector(descSelectors[i]);
    if(el&&(el.innerText||el.textContent||'').trim()){
      var value=(el.innerText||el.textContent||'').trim();
      if(value){desc=value;break;}
    }
  }
  var commentSelectors=['[data-e2e="comment-item"]'];
  var limit=Number(ctx.limitComments)||20;
  var comments=[];var seen={};
  for(var s=0;s<commentSelectors.length&&!comments.length;s++){
    var nodes=Array.from(document.querySelectorAll(commentSelectors[s]));
    for(var n=0;n<nodes.length&&comments.length<limit;n++){
      var txt=(nodes[n].innerText||'').trim();
      if(!txt||seen[txt])continue;
      seen[txt]=1;
      comments.push({text:txt.slice(0,300)});
    }
  }
  return {
    video_id:String(ctx.videoId||''),
    url:location.href,
    title:document.title||'',
    description:desc,
    comments:comments,
    comment_count:document.querySelectorAll('[data-e2e="comment-item"]').length,
    raw_excerpt:(document.body?document.body.innerText:'').slice(0,1500)
  };
}
